PREFIX wfkg: <https://example.org/wfkg/v1#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?cutoff ?articleId ?articleAvailableAt ?evidenceId ?evidenceAvailableAt ?eventId ?eventAvailableAt WHERE {
 VALUES ?cutoff {"2026-08-26T14:16:00+07:00"^^xsd:dateTime "2026-08-26T16:16:00+07:00"^^xsd:dateTime}
 ?a wfkg:articleId ?articleId; wfkg:availableAt ?articleAvailableAt; wfkg:reports ?e .
 ?v wfkg:evidenceId ?evidenceId; wfkg:extractedFrom ?a; wfkg:supports ?e; wfkg:availableAt ?evidenceAvailableAt .
 ?e wfkg:eventId ?eventId; wfkg:availableAt ?eventAvailableAt .
 FILTER(?articleAvailableAt <= ?cutoff && ?evidenceAvailableAt <= ?cutoff && ?eventAvailableAt <= ?cutoff)
} ORDER BY ?cutoff ?articleAvailableAt ?evidenceAvailableAt ?articleId ?evidenceId

PREFIX wfkg: <https://example.org/wfkg/v1#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?eventId ?status ?day (COUNT(DISTINCT ?o) AS ?day0Stock) (COUNT(DISTINCT ?i) AS ?day0Benchmark) (COUNT(DISTINCT ?r) AS ?reactions) WHERE {
 ?c a wfkg:EventStockCandidate; wfkg:forEvent ?e; wfkg:candidateStock ?stock; wfkg:candidateStatus ?status .
 ?e wfkg:eventId ?eventId; wfkg:effectiveTradingDate ?day .
 OPTIONAL {?stock wfkg:hasMarketObservation ?o . ?o wfkg:tradingDate ?day}
 OPTIONAL {?index wfkg:hasIndexObservation ?i . ?i wfkg:tradingDate ?day}
 OPTIONAL {?c wfkg:hasReaction ?r}
 } GROUP BY ?eventId ?status ?day ORDER BY ?eventId

PREFIX wfkg: <https://example.org/wfkg/v1#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?kind ?cutoff ?relation ?availableAt ?validTo ?periodEnd ?eligible WHERE {
 {
 VALUES (?cutoff ?cutoffDay ?oldestPeriod) {
 ("2026-08-26T14:16:00+07:00"^^xsd:dateTime "2026-08-26"^^xsd:date "2025-08-26"^^xsd:date)
 ("2026-08-26T16:16:00+07:00"^^xsd:dateTime "2026-08-26"^^xsd:date "2025-08-26"^^xsd:date) }
 VALUES (?kind ?left ?right) {
 (wfkg:LeadershipPosition wfkg:positionHolder wfkg:positionAtCompany)
 (wfkg:SubsidiaryRelation wfkg:subsidiaryCompany wfkg:parentCompany)
 (wfkg:IndexMembership wfkg:memberStock wfkg:memberIndex) }
 ?relation a ?kind; ?left ?a; ?right ?b; wfkg:validFrom ?start; wfkg:availableAt ?availableAt .
 OPTIONAL {?relation wfkg:positionTitle ?title}
 FILTER(?availableAt <= ?cutoff)
 FILTER NOT EXISTS {
 ?new a ?kind; ?left ?a; ?right ?b; wfkg:validFrom ?start; wfkg:availableAt ?newAt .
 OPTIONAL {?new wfkg:positionTitle ?newTitle}
 FILTER((!BOUND(?title) && !BOUND(?newTitle)) || ?title = ?newTitle)
 FILTER(?newAt <= ?cutoff && (?newAt > ?availableAt || (?newAt = ?availableAt && STR(?new) < STR(?relation)))) }
 OPTIONAL {?relation wfkg:validTo ?validTo}
 BIND(?start <= ?cutoffDay && (!BOUND(?validTo) || ?cutoffDay <= ?validTo) AS ?eligible)
 } UNION {
 VALUES (?cutoff ?cutoffDay ?oldestPeriod) {
 ("2026-08-26T14:16:00+07:00"^^xsd:dateTime "2026-08-26"^^xsd:date "2025-08-26"^^xsd:date)
 ("2026-08-26T16:16:00+07:00"^^xsd:dateTime "2026-08-26"^^xsd:date "2025-08-26"^^xsd:date) }
 BIND(wfkg:IndustryExposure AS ?kind)
 ?relation a wfkg:IndustryExposure; wfkg:exposureBank ?bank; wfkg:exposureIndustry ?industry; wfkg:periodType ?pt; wfkg:periodEnd ?periodEnd; wfkg:availableAt ?availableAt .
 FILTER(?pt = "YEAR")
 FILTER(?availableAt <= ?cutoff && ?periodEnd <= ?cutoffDay)
 FILTER NOT EXISTS {
 ?new a wfkg:IndustryExposure; wfkg:exposureBank ?bank; wfkg:exposureIndustry ?industry; wfkg:periodType ?pt; wfkg:periodEnd ?np; wfkg:availableAt ?na .
 FILTER(?na <= ?cutoff && ?np <= ?cutoffDay && (?np > ?periodEnd || (?np = ?periodEnd && (?na > ?availableAt || (?na = ?availableAt && STR(?new)<STR(?relation)))))) }
 BIND(?periodEnd >= ?oldestPeriod AS ?eligible)
 }
} ORDER BY ?kind ?cutoff ?relation

PREFIX wfkg: <https://example.org/wfkg/v1#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?eventId (COUNT(DISTINCT ?a) AS ?articles) (COUNT(DISTINCT ?c) AS ?candidates) (COUNT(DISTINCT ?r) AS ?reactions) WHERE {
 ?e wfkg:eventId ?eventId; wfkg:hasEventStockCandidate ?c . ?a wfkg:reports ?e . OPTIONAL {?c wfkg:hasReaction ?r}
 } GROUP BY ?eventId ORDER BY ?eventId

PREFIX wfkg: <https://example.org/wfkg/v1#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?reactionId ?kind ?observationId ?tradingDate ?adjustedClose ?returnValue ?availableAt ?source ?quality WHERE {
 ?r wfkg:reactionId ?reactionId .
 { ?r wfkg:derivedFromObservation ?o . BIND("STOCK" AS ?kind) }
 UNION { ?r wfkg:derivedFromIndexObservation ?o . BIND("BENCHMARK" AS ?kind) }
 ?o wfkg:observationId ?observationId; wfkg:tradingDate ?tradingDate; wfkg:adjustedClose ?adjustedClose; wfkg:returnValue ?returnValue; wfkg:availableAt ?availableAt; wfkg:sourceReference ?source; wfkg:dataQualityFlag ?quality .
 } ORDER BY ?reactionId ?kind ?tradingDate
